    for (int i = 0; i < 10; i++) {
      code += "f.prototype.argz = function() {arguments};";
      code += "f.prototype.devir" + i + " = function() {};";

      char letter = (char) ('d' + i);
      expected += "a.argz = function() {arguments};";
      expected += "function " + letter + "(c){}";
