    testSame("/a{4,}/");
    test("/a{3,}/",
         "/aaa+/");
    testSame("/a{4,6}/");
    testSame("/a{4,6}?/");
    test("/(?:a?)?/", "/a?/");
    test("/(?:a?)*/", "/a*/");
    test("/(?:a*)?/", "/a*/");
    test("/a(?:a*)?/", "/a+/");
