    test("/\\d{1,2}/",
         "/\\d\\d?/");
    test("/a*a*/", "/a*/");
    test("/a+a+/", "/aa+/");
    test("/a+a*/", "/a+/");
    // We don't conflate literal curly brackets with repetitions.
    testSame("/a\\{3,1}/");
    test("/a(?:{3,1})/", "/a\\{3,1}/");
    test("/a{3\\,1}/", "/a\\{3,1}/");
    testSame("/a\\{3}/");
    testSame("/a\\{3,}/");
    testSame("/a\\{1,3}/");
    // We don't over-escape curly brackets.
    testSame("/a{/");
    testSame("/a{}/");
    testSame("/a{x}/");
    testSame("/a{-1}/");
    testSame("/a{,3}/");
    testSame("/{{[a-z]+}}/");
    testSame("/{\\{0}}/");
    testSame("/{\\{0?}}/");
  }

