public void testSimple() {
    graph = LinkedDirectedGraph.create();
    graph.createNode("A");
    reachability = new GraphReachability<String, String>(graph);
    reachability.compute("A");
    assertReachable("A");

    graph.createNode("B");
    reachability = new GraphReachability<String, String>(graph);
    reachability.compute("A");
    assertReachable("A");
    assertNotReachable("B");

    graph.connect("A", "--->", "B");
    reachability = new GraphReachability<String, String>(graph);
    reachability.compute("B");
    assertNotReachable("A");
    assertReachable("B");

    graph.connect("B", "--->", "A");
    reachability = new GraphReachability<String, String>(graph);
    reachability.compute("B");
    assertReachable("A");
    assertReachable("B");

    graph.createNode("C");
    reachability = new GraphReachability<String, String>(graph);
    reachability.compute("A");
    assertReachable("A");
    assertReachable("B");
    assertNotReachable("C");

    graph.createNode("D");
    graph.connect("C", "--->", "D");
    reachability = new GraphReachability<String, String>(graph);
    reachability.compute("A");
    assertReachable("A");
    assertReachable("B");
    assertNotReachable("C");
    assertNotReachable("D");
    reachability.recompute("C");
    assertReachable("C");
    assertReachable("D");
  }

